'use strict';

import { createError, MISSING_DOC } from 'pouchdb-errors';

import { META_STORE } from './util';

export default function (txn, id, callback) {
  console.log('indexeddb._getLocal()', 'id:', id, 'callback:', typeof callback);

  if (txn.error) {
    return callback(txn.error);
  }

  txn.txn.objectStore(META_STORE).get(id).onsuccess = function (e) {
    const doc = e.target.result;

    txn.txn.commit(); // no more plans for this txn // TODO maybe can move this before result dereference

    if (!doc) {
      console.log('indexeddb._getLocal()', 'returning:', 'error:MISSING_DOC');
      callback(createError(MISSING_DOC, 'missing'));
      // FIXME can we just commit txn here?
      return;
    }

    console.log('indexeddb._getLocal()', 'doc:', JSON.stringify(doc));

    const rev = doc.rev;

    console.log('indexeddb._getLocal()', 'rev:', rev);

    console.log('indexeddb._getLocal()', 'getting result data...');

    const result = doc.revs[rev].data;
    result._id = doc.id;
    result._rev = rev;

    console.log('indexeddb._getLocal()', 'returning:', {
      doc: result,
      metadata: doc,
      ctx: txn
    });

    // WARNING: expecting possible old format
    callback(null, {
      doc: result,
      metadata: doc,
    });
  };
}
